package com.masterlearning.platform.modules.course.controller; import com.masterlearning.platform.common.api.ApiResponse; import com.masterlearning.platform.modules.course.dto.request.*; import com.masterlearning.platform.modules.course.dto.response.*; import com.masterlearning.platform.modules.course.service.*;
import com.masterlearning.platform.modules.course.security.CourseAuthorizationService;
import com.masterlearning.platform.modules.course.repository.CourseRepository; import jakarta.validation.Valid; import jakarta.persistence.EntityNotFoundException; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/courses") public class CourseController { private final CourseService service; private final CourseAuthorizationService authorization; private final CourseRepository courses; public CourseController(CourseService s, CourseAuthorizationService a, CourseRepository c){service=s;authorization=a;courses=c;} @PostMapping @ResponseStatus(HttpStatus.CREATED) @PreAuthorize("hasAnyRole('SUPER_ADMIN','ADMIN','INSTRUCTOR','TEACHER')") public ApiResponse<CourseResponse> create(@Valid @RequestBody CreateCourseRequest r){return ApiResponse.success("Course created successfully",service.create(r));} @GetMapping("/published") public ApiResponse<List<CourseResponse>> published(){return ApiResponse.success("Published courses retrieved successfully",service.published());} @PutMapping("/{id}/publish") @PreAuthorize("hasAnyRole('SUPER_ADMIN','ADMIN','INSTRUCTOR','TEACHER')") public ApiResponse<CourseResponse> publish(@PathVariable UUID id){var course=courses.findById(id).orElseThrow(()->new EntityNotFoundException("Course not found")); authorization.assertCanManage(course); return ApiResponse.success("Course published successfully",service.publish(id));} }